    best_t = None
    best_key = None
    for rx, ry in res:
        sd = man(sx, sy, rx, ry)
        od = man(ox, oy, rx, ry)
        gap = od - sd
        # Favor good reachability with positive gap; penalize edge.
        key = (-(gap), edge_penalty(rx, ry), sd, -od, opp_preference, rx, ry)
        # Also allow fallback if no positive gap exists.
