            sd = man(sx, sy, rx, ry)
            od = man(ox, oy, rx, ry)
            key = (sd, edge_penalty(rx, ry), -od, rx, ry)
            if best_key is None or key < best_key:
                best_key = key
                best_t = (rx, ry)

